WITH months AS (SELECT DISTINCT payroll_month month FROM warehouse_monthly_employee), head AS (SELECT payroll_month month,dept_id,SUM(month_end_headcount) closing_headcount FROM warehouse_monthly_employee GROUP BY 1,2), opening AS (SELECT m.month,d.dept_id,COUNT(h.emp_id) opening_headcount FROM months m CROSS JOIN warehouse_departments d LEFT JOIN staging_employees e ON e.hire_date<=date(m.month||'-01','-1 day') AND (e.separation_date='' OR e.separation_date>date(m.month||'-01','-1 day')) LEFT JOIN warehouse_employees h ON h.emp_id=e.emp_id AND h.valid_from<=date(m.month||'-01','-1 day') AND (h.valid_to='' OR h.valid_to>=date(m.month||'-01','-1 day')) AND h.dept_id=d.dept_id GROUP BY 1,2), sep AS (SELECT substr(e.separation_date,1,7) month,h.dept_id,COUNT(DISTINCT e.emp_id) separations FROM staging_employees e JOIN warehouse_employees h ON h.emp_id=e.emp_id AND h.valid_from<=e.separation_date AND (h.valid_to='' OR h.valid_to>=e.separation_date) WHERE e.separation_date<>'' GROUP BY 1,2) SELECT h.month,d.dept_name,o.opening_headcount,h.closing_headcount,(o.opening_headcount+h.closing_headcount)/2.0 average_headcount,COALESCE(s.separations,0) separations,COALESCE(s.separations,0)/NULLIF((o.opening_headcount+h.closing_headcount)/2.0,0) attrition_rate FROM head h JOIN opening o ON o.month=h.month AND o.dept_id=h.dept_id JOIN warehouse_departments d ON d.dept_id=h.dept_id LEFT JOIN sep s ON s.month=h.month AND s.dept_id=h.dept_id ORDER BY 1,2;
